#pragma once
#include "gw_token.h"
#include <stdexcept>

namespace fw::gw::portal {
// Shared parser treats element contents as spans, without XML entity decoding.
// Sessions generated by this backend use an ASCII hex alphabet, not user text.
inline std::string session_reply(std::string_view session) {
    if (session.empty() || session.size() > 256)
        throw std::invalid_argument("Invalid portal session length");
    for (char c : session)
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')))
            throw std::invalid_argument("Portal session must be lowercase hex");
    return "<Reply><Session>" + std::string(session) + "</Session></Reply>";
}

inline std::string token_reply(const GameToken& token) {
    return "<Reply><Token>" + format_token(token) + "</Token></Reply>";
}

inline std::string error_reply(std::uint16_t code, std::uint16_t server = 0,
                               std::uint16_t module = 0, std::uint16_t line = 0) {
    return "<Error code=\"" + std::to_string(code) + "\" server=\"" + std::to_string(server) +
           "\" module=\"" + std::to_string(module) + "\" line=\"" + std::to_string(line) + "\"/>";
}
}
